using System;using System.Data;using System.Reflection;using System.Windows.Forms;using System.ComponentModel;
class Check{static Control Find(Control root,string text){if(root.Text==text)return root;foreach(Control c in root.Controls){var found=Find(c,text);if(found!=null)return found;}return null;}static void dialogClose(){Application.OpenForms[Application.OpenForms.Count-1].Close();}[STAThread]static void Main(){var a=Assembly.LoadFrom("work/Videira-3.8.exe");var st=a.GetType("Videira.Store");if(st==null){foreach(var x in a.GetTypes())if(x.Name=="Store")st=x;}string root=System.IO.Path.Combine(Environment.CurrentDirectory,"work","sort-check-"+Guid.NewGuid());var db=Activator.CreateInstance(st,new object[]{root});var data=(DataSet)st.GetField("Data").GetValue(db);var pt=data.Tables["Produtos"];foreach(var n in new[]{10,2,1}){var r=pt.NewRow();r["Id"]=n;r["Código"]=n.ToString();r["Nome"]="TESTE "+n;r["Estoque"]=1m;r["Ativo"]="Sim";r["Fornecedor"]="Teste";r["Custo"]=10m;r["Preço"]=20m;r["Confirmado"]=true;pt.Rows.Add(r);}Type ft=null;foreach(var x in a.GetTypes())if(x.Name=="MainForm")ft=x;var form=(Form)Activator.CreateInstance(ft,new object[]{db,false,""});form.Show();var flags=BindingFlags.Instance|BindingFlags.NonPublic;ft.GetMethod("ShowPage",flags).Invoke(form,new object[]{"Produtos"});var grid=(DataGridView)ft.GetField("grid",flags).GetValue(form);if(grid.Rows[0].Cells["Código"].Value.ToString()!="1"||grid.Rows[1].Cells["Código"].Value.ToString()!="2"||grid.Rows[2].Cells["Código"].Value.ToString()!="10")throw new Exception("Ordem numérica incorreta");grid.Sort(grid.Columns["Nome"],ListSortDirection.Descending);ft.GetMethod("RefreshGrid",flags).Invoke(form,null);if(grid.SortedColumn.Name!="Nome"||grid.SortOrder!=SortOrder.Descending)throw new Exception("Ordenação escolhida não preservada");var product=pt.Rows.Find(1);product["Precificação automática"]="Não";var timer=new Timer{Interval=300};Exception error=null;timer.Tick+=(sender,args)=>{timer.Stop();try{var dialog=Application.OpenForms[Application.OpenForms.Count-1];var inventory=Find(dialog,"Estoque e cadastro");NumericUpDown stock=null;foreach(Control control in inventory.Controls)if(control is NumericUpDown&&control.Left<100)stock=(NumericUpDown)control;if(stock==null||!stock.Enabled)throw new Exception("Estoque bloqueado");stock.Value=7;using(var bmp=new System.Drawing.Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bmp,new System.Drawing.Rectangle(0,0,dialog.Width,dialog.Height));bmp.Save("work/product-edit38.png");}((Button)dialog.AcceptButton).PerformClick();}catch(Exception ex){error=ex;dialogClose();}};timer.Start();ft.GetMethod("Product",flags).Invoke(form,new object[]{product});if(error!=null)throw error;if((decimal)product["Estoque"]!=7m)throw new Exception("Ajuste não salvo");var movement=data.Tables["Movimentos"].Rows[data.Tables["Movimentos"].Rows.Count-1];if((decimal)movement["Quantidade"]!=6m)throw new Exception("Diferença incorreta");st.GetMethod("Atomic").Invoke(db,new object[]{(Action)(()=>st.GetMethod("AdjustProductStock").Invoke(db,new object[]{product,2m}))});if((decimal)product["Estoque"]!=2m)throw new Exception("Redução incorreta");form.Close();Console.WriteLine("PASS: códigos 1, 2, 10; ordenação por outra coluna preservada após atualizar; edição de estoque pela interface, aumento +6 e redução -5 registrados.");}}

